function createCounter({ start = 0, step = 1 } = {}) {
  let count = start; // private: only reachable through the returned functions
  return {
    increment() {
      count += step;
    },
    decrement() {
      count -= step;
    },
    reset() {
      count = start;
    },
    value() {
      return count;
    },
  };
}

function once(fn) {
  let called = false;
  let result;
  return function (...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  };
}

