weakset-cycle-detection.referenceSolution:
function hasCycle(value) {
  const path = new WeakSet();
  const done = new WeakSet();
  const visit = (node) => {
    if (node === null || typeof node !== 'object') return false;
    if (path.has(node)) return true;
    if (done.has(node)) return false;
    path.add(node);
    for (const key of Object.keys(node)) {
      if (visit(node[key])) return true;
    }
    path.delete(node);
    done.add(node);
    return false;
  };
  return visit(value);
}

function countObjects(root) {
  const seen = new WeakSet();
  let count = 0;
  const visit = (node) => {
    if (node === null || typeof node !== 'object' || seen.has(node)) return;
    seen.add(node);
    count++;
    for (const key of Object.keys(node)) visit(node[key]);
  };
  visit(root);
  return count;
}

weakset-cycle-detection.referenceSolutionTs:
function hasCycle(value: unknown): boolean {
  const path = new WeakSet<object>();
  const done = new WeakSet<object>();
  const visit = (node: unknown): boolean => {
    if (node === null || typeof node !== 'object') return false;
    const obj = node as object;
    if (path.has(obj)) return true;
    if (done.has(obj)) return false;
    path.add(obj);
    for (const key of Object.keys(obj)) {
      if (visit((obj as Record<string, unknown>)[key])) return true;
    }
    path.delete(obj);
    done.add(obj);
    return false;
  };
  return visit(value);
}

function countObjects(root: unknown): number {
  const seen = new WeakSet<object>();
  let count = 0;
  const visit = (node: unknown): void => {
    if (node === null || typeof node !== 'object') return;
    const obj = node as object;
    if (seen.has(obj)) return;
    seen.add(obj);
    count++;
    for (const key of Object.keys(obj)) {
      visit((obj as Record<string, unknown>)[key]);
    }
  };
  visit(root);
  return count;
}

